NotebookLoader.register({"id":"cloud-infrastructure","title":"Cloud & Infrastructure as Code","category":"Software engineering","status":"ready","description":"22 lessons, three stage projects and a locally runnable practice kit covering Azure infrastructure decisions, Terraform concepts, policy and safe lifecycle review.","level":"Foundations → intermediate → selected advanced practice","prerequisites":["Basic application, network and terminal concepts; earlier delivery, security and system-design paths are helpful.","Python 3.11+ for the offline lab. No cloud account, payment method or broker is required."],"outcomes":["Map Azure scope, identity and network responsibilities.","Review infrastructure desired state, dependencies and protected state.","Classify create/update/replacement/deletion and model cost arithmetic.","Run offline policy tests and inspect optional Azure Terraform schema validation.","Design credentialed delivery, data restoration, cost controls and verified teardown."],"setup":["Download the practice bundle and extract its flat files together.","From its folder run python infra_lab.py, then python -m unittest -v test_infra_lab.py.","Read README.md and workbook.md before optional external tooling. The verified baseline is local only."],"nextSteps":["Choose a disposable subscription scope deliberately; review costs, identity and cleanup before optional real cloud work.","Integrate the full-stack project journey and retain an evidence ledger for remaining live boundary tests."],"sources":[{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview"},{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/"},{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"},{"title":"Azure Virtual Network","url":"https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"},{"title":"Azure Terraform managed identity authentication","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/authenticate-to-azure-with-managed-identity-for-azure-services"},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state"},{"title":"Terraform modules","url":"https://developer.hashicorp.com/terraform/language/modules"},{"title":"Terraform variables","url":"https://developer.hashicorp.com/terraform/language/values/variables"},{"title":"Terraform state locking","url":"https://developer.hashicorp.com/terraform/language/state/locking"},{"title":"Terraform lifecycle","url":"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle"},{"title":"Terraform import","url":"https://developer.hashicorp.com/terraform/language/import"},{"title":"Azure budgets","url":"https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets"},{"title":"Terraform tests","url":"https://developer.hashicorp.com/terraform/language/tests"}],"lessons":[{"id":"cloud-contract","title":"1. Cloud is a responsibility boundary","takeaway":"Managed infrastructure still needs an application owner.","sections":[{"title":"Understand the contract","paragraphs":["Cloud services rent compute, storage, networking and managed capabilities through provider APIs. A service model determines which operating tasks the provider performs and which remain yours. Running an application on managed compute does not automatically configure authorization, protect application data, establish backups or enforce cost limits."]},{"title":"Work through the example","paragraphs":["The notebook can remain a static GitHub Pages site. A future private full-stack notebook needs an API, identity, data store and operational owner. Choosing managed services changes the work required; it does not justify adding a cloud service to every feature."]}],"quiz":{"question":"Managed infrastructure still needs an application owner. Which decision follows?","options":["Assign an owner to application security, data recovery and spending.","Assume a managed service makes the entire workload secure automatically.","Assume the provider's infrastructure backup proves the application's point-in-time recovery target."],"correct":0,"explanation":"Managed infrastructure shifts particular responsibilities rather than removing workload ownership."},"references":[{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."},{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."}],"stage":"foundation","exercise":{"prompt":"List responsibilities for static hosting, a VM and a managed database. Name who patches the guest OS, grants application access, validates restores and responds to a leak. Treat the offline kit as design practice only.","checks":["Compare guest OS responsibility for a VM versus managed service.","Name owners for application access and restore verification."],"solution":"Static hosting owns web asset delivery while the learner owns content and browser behavior. A VM adds guest OS patching and service operations. Managed databases reduce selected engine operations but retain application access, backup configuration and restore verification responsibilities. Assign an owner to leaks, identity and recovery instead of assuming a service model solves them.","solutionFormat":"prose"}},{"id":"azure-scope","title":"2. Azure tenant, subscription and resource group","takeaway":"Verify identity, billing scope and ownership before a plan.","sections":[{"title":"Understand the contract","paragraphs":["A tenant is an identity directory; a subscription is a resource and billing scope; a resource group organizes related resources. Region determines resource placement subject to service support. Names and labels cannot substitute for checking the actual subscription ID. Resource groups should have a lifecycle owner, purpose and expiry for temporary learning work."]},{"title":"Work through the example","paragraphs":["A developer belongs to two tenants and has access to a work and personal subscription. A familiar resource-group name can exist in the wrong subscription. The optional template requires an explicit subscription_id and creates only a named training resource group if separately applied."]}],"quiz":{"question":"Verify identity, billing scope and ownership before a plan. Which decision follows?","options":["Require explicit scope and lifecycle metadata before real provisioning.","Infer the target subscription from the current CLI default.","Use matching resource-group names as proof that two plans target the same subscription."],"correct":0,"explanation":"Ambient account defaults can drift; a deliberate scope check is a deployment prerequisite."},"references":[{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","section":"Principal; role definition; scope; additive assignments","reviewed":"2026-09-30","scope":"Azure management and supported data-plane authorization; notebook simulations do not authenticate to Azure."},{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."}],"stage":"foundation","exercise":{"prompt":"Write a preflight sheet with tenant, subscription, region, resource group, purpose, owner and expiry. Do not paste tokens into the workbook. Review the offline topology.json to see how its fake subscription is clearly marked.","checks":["Record explicit identity and subscription scope.","Distinguish a fictional fixture from a verified real deployment target."],"solution":"The preflight records tenant and subscription IDs, chosen region, isolated resource-group name, owner, purpose and expiry. Verify both identity and billing scope before real actions; the fixture's fake subscription has no cloud target. Do not record tokens. A familiar name or current CLI default is insufficient scope evidence.","solutionFormat":"prose"}},{"id":"requirements","title":"3. Workload requirements and service selection","takeaway":"Select services from workload constraints and reversible tradeoffs.","sections":[{"title":"Understand the contract","paragraphs":["Start with users, data sensitivity, request pattern, recovery targets and deployment frequency. Compare static hosting, managed application compute and VMs. A container orchestrator is useful for some workloads but introduces extra operations. Define what must be measured rather than claiming a provider icon guarantees performance or availability."]},{"title":"Work through the example","paragraphs":["A personal notebook needs mostly cached static assets. A collaborative project adds authenticated writes and a database. For a training API, managed application compute can reduce OS work; Kubernetes can be a learning choice, but its cluster lifecycle is an additional responsibility."]}],"quiz":{"question":"Select services from workload constraints and reversible tradeoffs. Which decision follows?","options":["Document constraints and compare two viable service models.","Use Kubernetes for every workload because it appears advanced.","Select the cheapest compute line item and ignore database, egress and monitoring responsibilities."],"correct":0,"explanation":"Architecture should address stated needs and make its operational and financial costs visible."},"references":[{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."},{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."}],"stage":"foundation","exercise":{"prompt":"Write a two-option ADR for your full-stack project. Include baseline monthly cost categories without claiming current prices, and name the trigger that would justify changing the architecture.","checks":["Compare two options against stated workload constraints.","Include a measurable decision trigger and avoid invented current pricing."],"solution":"Compare managed application compute with a VM against authenticated writes, sensitive data, operational ownership, recovery and deployment requirements. Keep static hosting for read-only needs. Record cost categories and current-pricing lookup instead of fixed fictional rates. Define a measurable trigger such as required OS customization that could justify switching models.","solutionFormat":"prose"}},{"id":"networking","title":"4. Networks, DNS and traffic boundaries","takeaway":"Connectivity requires routing, name resolution and permitted access.","sections":[{"title":"Understand the contract","paragraphs":["A virtual network provides address space and subnets for supported services. Routes determine where traffic goes; filters determine whether traffic is permitted; DNS resolves names. A private endpoint alone is not enough if the client resolves a public address or lacks access to the connected network. Overlapping address ranges complicate later peering."]},{"title":"Work through the example","paragraphs":["A training API calls private storage. Draw client, API, resolver and storage endpoint. Mark which paths are public, which are private and which identity authorizes data access. The supplied Azure storage template disables public networking and supplies no private endpoint, so it is intentionally not an accessible application backend."]}],"quiz":{"question":"Connectivity requires routing, name resolution and permitted access. Which decision follows?","options":["Check DNS, network path and authorization as separate gates.","Assume private networking automatically grants permission to read data.","Create a private endpoint and assume every client automatically resolves and reaches it."],"correct":0,"explanation":"Network reachability and data authorization are independent controls."},"references":[{"title":"Azure Virtual Network","url":"https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","section":"Communication; filtering; routing","reviewed":"2026-09-30","scope":"Azure networking overview; actual private connectivity also requires DNS and identity configuration."},{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","section":"Principal; role definition; scope; additive assignments","reviewed":"2026-09-30","scope":"Azure management and supported data-plane authorization; notebook simulations do not authenticate to Azure."}],"stage":"foundation","exercise":{"prompt":"In the offline topology change storage to public and run policy tests. Restore the fixture. On paper diagnose three failures separately: wrong DNS result, blocked route, and valid connection with denied identity.","checks":["Diagnose DNS, routing/filter and authorization failures separately.","State the template's missing private-connectivity prerequisites."],"solution":"The request needs intended DNS resolution, a reachable route/filter path and authorized data action. Public storage should fail the training policy. A private endpoint does not itself grant identity permission. The supplied template disables public networking but creates no private endpoint or connected application network, so it is not a complete usable backend.","solutionFormat":"prose"},"diagram":{"title":"Three independent access gates","summary":"A private endpoint or route is insufficient without DNS and authorization.","nodes":[{"id":"0","label":"Application","description":"Starts an intended storage request."},{"id":"1","label":"DNS","description":"Resolves the intended endpoint."},{"id":"2","label":"Network path","description":"Routes and filters must permit traffic."},{"id":"3","label":"Authorization","description":"Valid identity must have data action rights.","shape":"decision"},{"id":"4","label":"Storage data","description":"Accessible only after all required gates.","shape":"database"}],"edges":[{"from":"0","to":"1","label":"resolve"},{"from":"1","to":"2","label":"connect"},{"from":"2","to":"3","label":"present identity"},{"from":"3","to":"4","label":"authorized action"}],"steps":[{"title":"1. resolve","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Resolves the intended endpoint."},{"title":"2. connect","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Routes and filters must permit traffic."},{"title":"3. present identity","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Valid identity must have data action rights."},{"title":"4. authorized action","activeNodes":["3","4"],"activeEdges":[3],"explanation":"Accessible only after all required gates."}],"direction":"LR"}},{"id":"identity","title":"5. Identity and least privilege","takeaway":"Choose a principal, role and scope for each responsibility.","sections":[{"title":"Understand the contract","paragraphs":["Azure RBAC assignments combine principal, role definition and scope. Management-plane rights and supported data-plane rights are distinct. Roles are generally additive; a narrow assignment does not erase a broader assignment elsewhere. Managed identity can avoid stored client secrets for compatible Azure-hosted workloads, but local workstations do not automatically have that identity."]},{"title":"Work through the example","paragraphs":["The API needs to read one storage container, while the deployment identity creates a storage account in one resource group. These are different responsibilities and should not both receive subscription Owner. The optional template deliberately creates no role assignments because granting a real principal requires an explicit reviewed identity choice."]}],"quiz":{"question":"Choose a principal, role and scope for each responsibility. Which decision follows?","options":["Grant separate narrowly scoped deployment and runtime permissions.","Give every component subscription Owner to avoid troubleshooting.","Add a resource-level Reader assignment and assume it removes an existing subscription Owner grant."],"correct":0,"explanation":"Least privilege and negative tests reduce impact while keeping distinct management and data responsibilities visible."},"references":[{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","section":"Principal; role definition; scope; additive assignments","reviewed":"2026-09-30","scope":"Azure management and supported data-plane authorization; notebook simulations do not authenticate to Azure."},{"title":"Azure Terraform managed identity authentication","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/authenticate-to-azure-with-managed-identity-for-azure-services","section":"Configure and authenticate managed identity","reviewed":"2026-09-30","scope":"Azure-hosted identity workflow; a local workstation does not automatically receive managed identity."}],"stage":"foundation","exercise":{"prompt":"Write allowed and denied actions for deployment, API and reviewer. Include the broader-assignment check. Local policy tests exercise a simplified matrix, not Azure token acquisition or real RBAC enforcement.","checks":["Separate deployment management rights from runtime data rights.","Include a broader/inherited-role check and denied example."],"solution":"The deployment identity can manage the isolated resource-group resources while the runtime identity gets only required data actions. Review broader inherited assignments because adding a narrow role does not remove wider rights. Test actual allowed/denied access in a separately chosen environment; the local matrix is only design evidence.","solutionFormat":"prose"}},{"id":"iac-model","title":"6. Desired state and infrastructure as code","takeaway":"Version configuration, inspect differences and review changes.","sections":[{"title":"Understand the contract","paragraphs":["Infrastructure as code expresses desired resources and parameters so changes can be reviewed and reproduced. Terraform uses providers to interact with remote APIs and state to associate addresses with existing objects. Configuration is not the entire deployed system: manual drift, data contents and provider defaults also matter."]},{"title":"Work through the example","paragraphs":["Changing an owner tag should update metadata; changing a resource name may force replacement depending on provider schema. The offline planner models these cases using a small JSON inventory. It does not parse HCL or implement Terraform provider semantics.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"from infra_lab import plan\nimport json\nfrom pathlib import Path\n\ndesired = json.loads(Path('topology.json').read_text())['resources']\nprint(plan([], desired))  # create group; create store\nprint(plan(desired, desired))  # no-op for both"}],"quiz":{"question":"Version configuration, inspect differences and review changes. Which decision follows?","options":["Review the difference between desired configuration, state association and real resources.","Treat committed JSON as proof the cloud already matches it.","Replace the state file with desired JSON and consider the remote resources reconciled."],"correct":0,"explanation":"Desired state becomes reality only through provider operations and observed verification."},"references":[{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"foundation","exercise":{"prompt":"Run python infra_lab.py and compare create/update/replace actions. Identify which configuration property caused each action. Keep simulated results clearly separate from terraform plan output.","checks":["Classify create, tag update and identity replacement in the model.","Label inventory model results separately from real Terraform output."],"solution":"The configuration expresses desired inventory while state associates addresses and observed resources may drift. The teaching plan creates absent IDs, updates changed tags and replaces changed identity/name. Its output is a local model, not Terraform provider output. A reviewed plan still requires executed operations and observation before describing a deployed result.","solutionFormat":"prose"}},{"id":"provider-init","title":"7. Providers, versions and initialization","takeaway":"Pin compatible dependencies and verify the tool boundary.","sections":[{"title":"Understand the contract","paragraphs":["Terraform core and provider plugins evolve separately. required_version constrains core; required_providers identifies sources and version constraints. terraform init initializes the backend and obtains modules/providers. A dependency lock file records selected provider versions and checksums; a broad constraint alone does not reproduce an exact selection."]},{"title":"Work through the example","paragraphs":["The Azure JSON template targets Terraform >=1.6 and <2 with AzureRM ~>4.0. That allows compatible 4.x provider selections; the learner must retain their generated lock file and record actual versions. Init needs internet or a configured plugin mirror; it is not an offline test."]}],"quiz":{"question":"Pin compatible dependencies and verify the tool boundary. Which decision follows?","options":["Record actual tool versions and preserve the generated provider lock selection.","Assume a version constraint is the same as a committed lock file.","Delete the provider lock file before every release so all environments select their own newest version."],"correct":0,"explanation":"Constraints allow a range; the lock selection records the dependency actually chosen."},"references":[{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."},{"title":"Terraform modules","url":"https://developer.hashicorp.com/terraform/language/modules","section":"Module structure; using modules","reviewed":"2026-09-30","scope":"Terraform 1.x module concepts; provider-specific schemas need validation."}],"stage":"foundation","exercise":{"prompt":"Optional in a separate empty folder: copy main.tf.json, run terraform init -backend=false, then terraform validate. Record core and selected provider versions. No Azure apply is required and validation is not an account availability test.","checks":["Record actual core and locked provider selections.","Distinguish dependency initialization from cloud provisioning and validation."],"solution":"Copy only the Azure template into a separate folder, initialize without a backend and validate using the selected provider. Record core and provider versions and preserve the generated lock selection. A compatible range can select different versions; initialization requires network/mirror and schema validation does not deploy or prove account availability.","solutionFormat":"prose"}},{"id":"variables","title":"8. Variables, validation and outputs","takeaway":"Define typed inputs and avoid secrets in state or examples.","sections":[{"title":"Understand the contract","paragraphs":["Inputs let one configuration express several intentional environments. Use type constraints and validation for names, location and acceptable values. Outputs expose selected results, but marking a value sensitive masks presentation rather than encrypting state. Secrets can enter configuration, state, plans and logs; protect all of them."]},{"title":"Work through the example","paragraphs":["The template validates a lower-case storage name and requires subscription_id rather than using a hardcoded credential. Tags carry learning purpose and expiry. Outputting a storage account ID is different from outputting its keys; the teaching template exposes only the resource-group ID.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"{\n  \"variable\": {\n    \"storage_name\": {\n      \"type\": \"string\",\n      \"description\": \"Account name; full validation appears in main.tf.json.\"\n    }\n  }\n}"}],"quiz":{"question":"Define typed inputs and avoid secrets in state or examples. Which decision follows?","options":["Validate public inputs and protect state even when values are marked sensitive.","Commit secrets after adding a sensitive=true display flag.","Output an access key marked sensitive and assume saved state no longer contains it."],"correct":0,"explanation":"Sensitive masking is not confidentiality for stored plans, state or repository history."},"references":[{"title":"Terraform variables","url":"https://developer.hashicorp.com/terraform/language/values/variables","section":"Type constraints; validation; sensitive values","reviewed":"2026-09-30","scope":"Terraform 1.x input contracts; sensitive display masking is not encryption."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"foundation","exercise":{"prompt":"Compare a bad storage name containing hyphens with a valid lower-case alphanumeric one. Trace where a hypothetical connection secret could appear and choose a runtime secret-delivery mechanism instead of putting it in a sample variable file.","checks":["Identify why a hyphenated name fails and a valid name passes.","Trace secret exposure beyond display masking."],"solution":"A hyphenated storage name fails the full template's lower-case alphanumeric 3-24 character validation. Explicit typed inputs are public configuration contracts. A sensitive flag masks output but secrets may remain in state, saved plans and logs; use an appropriate runtime identity/secret mechanism and protect those artifacts.","solutionFormat":"prose"}},{"id":"dependencies","title":"9. Dependency graph and outputs","takeaway":"References describe dependency without requiring a universal sequence.","sections":[{"title":"Understand the contract","paragraphs":["Terraform derives dependencies from expressions that reference other resources. A storage account reference to a resource-group name establishes that relationship; independent resources may execute concurrently. depends_on can represent hidden dependencies but excessive blanket dependencies slow plans and make unknown values spread."]},{"title":"Work through the example","paragraphs":["The template storage account uses the created resource-group name and location through references. The graph has group before account, not group before every resource in every environment. A private endpoint would add further dependencies if intentionally designed."]}],"quiz":{"question":"References describe dependency without requiring a universal sequence. Which decision follows?","options":["Use resource references for actual dependencies and avoid artificial total ordering.","Add depends_on from every resource to every other resource.","Serialize all resources with blanket depends_on to make every unknown value known before planning."],"correct":0,"explanation":"A dependency graph expresses necessary constraints; unrelated resources need not be serialized."},"references":[{"title":"Terraform modules","url":"https://developer.hashicorp.com/terraform/language/modules","section":"Module structure; using modules","reviewed":"2026-09-30","scope":"Terraform 1.x module concepts; provider-specific schemas need validation."},{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."}],"stage":"intermediate","exercise":{"prompt":"Inspect main.tf.json and draw only real dependencies. Distinguish a dependency edge from a request at runtime. Do not interpret the diagram as proof that the configured storage data endpoint is reachable.","checks":["Draw only the resource reference relationships in the supplied template.","Distinguish dependency graph edges from runtime request sequence."],"solution":"The storage account references the group's name/location, establishing group-before-account; the selected output references the group's ID. These are configuration dependencies, not runtime storage calls. Independent resources can proceed concurrently. Private endpoint/DNS dependencies would need explicit design if added later.","solutionFormat":"prose"},"diagram":{"title":"Configuration dependencies","summary":"Resource references produce a partial order, not a runtime request trace.","nodes":[{"id":"0","label":"Typed inputs","description":"Explicit subscription, location and naming."},{"id":"1","label":"Resource group","description":"Azure grouping and lifecycle scope."},{"id":"2","label":"Storage account","description":"References group name and location; private access is not supplied.","shape":"database"},{"id":"3","label":"Output","description":"Exposes resource-group ID, not a credential."}],"edges":[{"from":"0","to":"1","label":"configure"},{"from":"1","to":"2","label":"reference dependency"},{"from":"1","to":"3","label":"expose selected ID"}],"steps":[{"title":"1. configure","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Azure grouping and lifecycle scope."},{"title":"2. reference dependency","activeNodes":["1","2"],"activeEdges":[1],"explanation":"References group name and location; private access is not supplied."},{"title":"3. expose selected ID","activeNodes":["1","3"],"activeEdges":[2],"explanation":"Exposes resource-group ID, not a credential."}],"direction":"LR"}},{"id":"state","title":"10. State, remote backends and locks","takeaway":"State is sensitive coordination data, not an application backup.","sections":[{"title":"Understand the contract","paragraphs":["State maps Terraform addresses to remote resource identities and stores attributes. It can contain secrets. A remote backend can centralize access and versioning; locking depends on backend support. Application rows and blob contents require their own backups. Deleting state does not safely delete resources and can make future plans propose duplicates."]},{"title":"Work through the example","paragraphs":["Two engineers applying different changes against separate state files can overwrite assumptions about the same real object. A shared lock-capable backend limits concurrent state writes, while protected state backups support recovery. The optional template uses local state unless the learner intentionally designs a remote backend."]}],"quiz":{"question":"State is sensitive coordination data, not an application backup. Which decision follows?","options":["Protect shared state and handle active locks deliberately.","Delete the lock whenever a deployment appears slow.","Restore application rows by restoring only the Terraform state snapshot."],"correct":0,"explanation":"A live operation may still own the lock; bypassing it can permit conflicting state writes."},"references":[{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."},{"title":"Terraform state locking","url":"https://developer.hashicorp.com/terraform/language/state/locking","section":"State locking; force-unlock","reviewed":"2026-09-30","scope":"Lock support depends on backend; local lab tests no real distributed lock."}],"stage":"intermediate","exercise":{"prompt":"Describe state access, encryption, version recovery and lock ownership. Explain why force-unlock is only appropriate after confirming no live operation owns the lock. Do not commit *.tfstate, saved plans or credentials.","checks":["Separate state recovery from application-data restoration.","Explain the active-owner check required before force-unlock."],"solution":"Protect state access, encryption and versioned recovery with a compatible lock-capable backend if collaborating. A lock owner may still be active even during a slow operation; force-unlock needs proof that no live owner remains. Application rows/blobs need separate backups. Local state in this optional template is not an automatically configured remote backend.","solutionFormat":"prose"},"diagram":{"title":"State association and data are different","summary":"Protected state maps configuration addresses; it does not contain a backup of application rows.","nodes":[{"id":"0","label":"Configuration","description":"Desired resources and reviewed parameters."},{"id":"1","label":"State","description":"Sensitive resource identity association.","shape":"database"},{"id":"2","label":"Provider","description":"Calls selected remote APIs."},{"id":"3","label":"Cloud resources","description":"Real observed infrastructure."},{"id":"4","label":"Application backups","description":"Separate recovery responsibility.","shape":"database"}],"edges":[{"from":"0","to":"2","label":"desired operations"},{"from":"1","to":"2","label":"existing identity"},{"from":"2","to":"3","label":"planned and executed changes"},{"from":"3","to":"4","label":"protect actual data separately"}],"steps":[{"title":"1. desired operations","activeNodes":["0","2"],"activeEdges":[0],"explanation":"Calls selected remote APIs."},{"title":"2. existing identity","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Calls selected remote APIs."},{"title":"3. planned and executed changes","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Real observed infrastructure."},{"title":"4. protect actual data separately","activeNodes":["3","4"],"activeEdges":[3],"explanation":"Separate recovery responsibility."}],"direction":"LR"}},{"id":"plan-review","title":"11. Plan review and change classification","takeaway":"A plan is a proposed operation set, not a successful deployment.","sections":[{"title":"Understand the contract","paragraphs":["Read additions, in-place changes, replacements and deletions resource by resource. Unknown-after-apply values may be legitimate but deserve attention where they affect safety. A saved plan contains sensitive information and can become inappropriate if surrounding conditions change. Review identity, scope, provider selection and destructive actions before applying."]},{"title":"Work through the example","paragraphs":["The offline planner replaces storage when its teaching identity name changes, and flags deletion when a desired ID is absent. It requires a separate allow_destroy argument for simulated destructive actions. This is a local policy contract, not Terraform replacement metadata.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"from infra_lab import plan, simulate_apply\nimport json\nfrom pathlib import Path\n\ncurrent = json.loads(Path('topology.json').read_text())['resources']\nprint(plan(current, []))  # two destroy operations in the MODEL\n# simulate_apply(current, []) raises ValueError\nprint(simulate_apply(current, [], allow_destroy=True))  # []\n# No cloud or filesystem resource is created/deleted."}],"quiz":{"question":"A plan is a proposed operation set, not a successful deployment. Which decision follows?","options":["Review replacement and deletion effects, then verify after any separately chosen deployment.","Treat a successful plan as evidence that resources were created.","Treat every in-place update as operationally safe because it is not labeled destroy."],"correct":0,"explanation":"Planning predicts operations; only executed operations and observed results establish deployed state."},"references":[{"title":"Terraform lifecycle","url":"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle","section":"create_before_destroy; prevent_destroy; ignore_changes","reviewed":"2026-09-30","scope":"Terraform lifecycle behavior, including limitations; no resource lifecycle operation is executed here."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"intermediate","exercise":{"prompt":"Run the planner tests for create, no-op, update, replace and destroy. In workbook.md explain which actions need a data migration or backup. No command in the supplied kit invokes terraform apply.","checks":["Classify all five model actions, including no-op.","Name the data consequences of replace/destroy and the unexecuted cloud boundary."],"solution":"The model reports create for absent IDs, update for changed tags, replace for changed kind/name and destroy for removed desired IDs. Replacements/deletions require explicit local opt-in. Review data migration and recovery before real destructive operations. No supplied operation invokes Terraform apply, and model output cannot prove cloud creation.","solutionFormat":"prose"},"diagram":{"title":"Plan is an evidence gate","summary":"A successful proposed change is not proof of deployment.","nodes":[{"id":"0","label":"Validation","description":"Check configuration and selected contracts."},{"id":"1","label":"Plan","description":"Inspect create/update/replace/destroy."},{"id":"2","label":"Review","description":"Confirm scope, data migration and cost.","shape":"decision"},{"id":"3","label":"Optional deliberate apply","description":"Only after independently choosing real work."},{"id":"4","label":"Observe and recover","description":"Check service behavior and retain teardown evidence."}],"edges":[{"from":"0","to":"1","label":"prepare"},{"from":"1","to":"2","label":"inspect"},{"from":"2","to":"3","label":"approved real operation"},{"from":"3","to":"4","label":"verify actual outcome"}],"steps":[{"title":"1. prepare","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Inspect create/update/replace/destroy."},{"title":"2. inspect","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Confirm scope, data migration and cost."},{"title":"3. approved real operation","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Only after independently choosing real work."},{"title":"4. verify actual outcome","activeNodes":["3","4"],"activeEdges":[3],"explanation":"Check service behavior and retain teardown evidence."}],"direction":"LR"}},{"id":"lifecycle","title":"12. Replacement and lifecycle safeguards","takeaway":"Protect data across resource identity changes.","sections":[{"title":"Understand the contract","paragraphs":["create_before_destroy can create a replacement first when the service permits coexistence, but unique naming and quotas can prevent that. prevent_destroy blocks certain configuration-driven destruction while present; removing the resource block also removes that protection. ignore_changes intentionally delegates selected drift and can conceal unexpected changes if used broadly."]},{"title":"Work through the example","paragraphs":["Renaming a storage account is not equivalent to editing an owner tag. The provider may require a new account while data remains in the old one. The learner must copy and validate data, switch clients and retain recovery options rather than assuming replacement migrates contents."]}],"quiz":{"question":"Protect data across resource identity changes. Which decision follows?","options":["Review replacement data movement and the limits of lifecycle guards.","Assume create_before_destroy automatically copies stored data.","Set ignore_changes on all attributes so future drift cannot threaten availability."],"correct":0,"explanation":"Lifecycle ordering manages resource operations; application data migration remains a separate task."},"references":[{"title":"Terraform lifecycle","url":"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle","section":"create_before_destroy; prevent_destroy; ignore_changes","reviewed":"2026-09-30","scope":"Terraform lifecycle behavior, including limitations; no resource lifecycle operation is executed here."}],"stage":"intermediate","exercise":{"prompt":"Write a rename migration with copy verification, switch criterion and rollback deadline. Explain why deleting a resource block should still be reviewed even if prevent_destroy once appeared in it.","checks":["Include copy verification, switch criterion and rollback deadline.","Describe the limits of create_before_destroy and removed prevent_destroy configuration."],"solution":"For storage rename, create a permitted new account, copy synthetic data with integrity checks, switch clients under an explicit criterion and retain rollback until the deadline. create_before_destroy does not copy data or bypass unique-name/quota constraints. Removing a block removes its prevent_destroy configuration; deletion still needs review.","solutionFormat":"prose"}},{"id":"modules","title":"13. Modules and environment boundaries","takeaway":"Reuse a contract without hiding ownership or mixing environments.","sections":[{"title":"Understand the contract","paragraphs":["A module packages resources with typed inputs and outputs. Keep contracts small and avoid passing every provider field through without design. Development and production need distinct state, access and lifecycle policies. Terraform workspaces provide multiple states for one configuration but are not complete isolation of credentials, policy or organizational boundaries."]},{"title":"Work through the example","paragraphs":["A storage module could accept name, region and approved tags, and expose its ID. It should state networking prerequisites. The supplied single-file template is intentionally a readable foundation; turning it into a module is a learner extension, not a hidden generated abstraction."]}],"quiz":{"question":"Reuse a contract without hiding ownership or mixing environments. Which decision follows?","options":["Separate reuse from access and state isolation.","Assume a workspace name alone prevents production access.","Embed production credentials in the reusable module so all environments share its behavior."],"correct":0,"explanation":"Workspace selection does not replace separate credentials, permissions and organizational controls."},"references":[{"title":"Terraform modules","url":"https://developer.hashicorp.com/terraform/language/modules","section":"Module structure; using modules","reviewed":"2026-09-30","scope":"Terraform 1.x module concepts; provider-specific schemas need validation."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"intermediate","exercise":{"prompt":"Design a module interface with three essential inputs and one useful output. Explain how production credentials and state remain inaccessible to a development runner even if both use the same module source.","checks":["Define a small typed module contract and useful output.","Explain how a development runner is denied production identity/state access."],"solution":"A small storage module can accept approved name, region and tags and return its resource ID while documenting connectivity prerequisites. Development and production need distinct credentials, state permissions and lifecycle ownership. Reusing module source is compatible with isolation; workspace names alone cannot enforce that access boundary.","solutionFormat":"prose"}},{"id":"drift-import","title":"14. Drift detection and adopting existing resources","takeaway":"Import associates identity; review configuration before changing it.","sections":[{"title":"Understand the contract","paragraphs":["Manual cloud changes can cause drift from configuration. A normal refreshed plan may propose restoring configured values. Decide whether an emergency change should be codified or reverted. Import associates an existing object with an address but does not automatically document every intended property or prove the next plan is safe."]},{"title":"Work through the example","paragraphs":["An operator temporarily enables public storage access during troubleshooting. The next plan should reveal the divergence; the security owner decides a controlled remediation. Importing an existing account needs exactly one intended state owner to avoid competing management."]}],"quiz":{"question":"Import associates identity; review configuration before changing it. Which decision follows?","options":["Review drift and adoption under a single explicit resource owner.","Import an existing object and apply immediately without inspecting the plan.","Manage the same imported resource from two state files to gain deployment redundancy."],"correct":0,"explanation":"State association is only the start of adoption; configuration can still propose destructive or unsafe changes."},"references":[{"title":"Terraform import","url":"https://developer.hashicorp.com/terraform/language/import","section":"Import existing resources","reviewed":"2026-09-30","scope":"Import establishes a state association; adoption still requires configuration and a reviewed plan."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"intermediate","exercise":{"prompt":"Use the offline model to change a tag and compare drift. Draft an adoption checklist: scope, identity, one owner, backup, matching configuration, non-destructive reviewed plan. Do not import a shared resource for this exercise.","checks":["Identify a deliberate decision for manual drift.","List scope, one owner and reviewed plan as adoption gates."],"solution":"A tag drift changes observed inventory and should be deliberately codified or reverted by its owner. For adoption verify scope, resource ID and a single state owner, protect data, write matching configuration and inspect a non-destructive refreshed plan before mutation. Import only establishes an association; it is not automatic safe reconciliation.","solutionFormat":"prose"}},{"id":"policy","title":"15. Policy checks and evidence limits","takeaway":"Static checks catch selected mistakes without proving real enforcement.","sections":[{"title":"Understand the contract","paragraphs":["Policy checks can reject missing owner/expiry tags, public endpoints or overbroad roles. Such checks are useful before a plan but can be bypassed if the real deployment path ignores them. Full authorization and network enforcement require tests against actual services. A locally passing JSON contract is evidence about that JSON only."]},{"title":"Work through the example","paragraphs":["infra_lab.py rejects public storage, wildcard roles and incomplete metadata in topology.json. It does not inspect an Azure tenant or enforce Azure Policy. The Azure template disables public networking but does not provide a complete private application network.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"from infra_lab import validate\nimport json\nfrom pathlib import Path\n\nresources = json.loads(Path('topology.json').read_text())['resources']\nresources[1]['public_network'] = True\ntry:\n    validate(resources)\nexcept ValueError as error:\n    print(error)  # public storage forbidden by training policy"}],"quiz":{"question":"Static checks catch selected mistakes without proving real enforcement. Which decision follows?","options":["Combine static policies with actual enforcement tests at the target boundary.","Claim the real cloud is secure after mock policy tests pass.","Assume a local policy result prevents manual portal changes made by another authorized user."],"correct":0,"explanation":"Selected fixture checks cannot establish account configuration or live enforcement."},"references":[{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","section":"Principal; role definition; scope; additive assignments","reviewed":"2026-09-30","scope":"Azure management and supported data-plane authorization; notebook simulations do not authenticate to Azure."},{"title":"Azure Virtual Network","url":"https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","section":"Communication; filtering; routing","reviewed":"2026-09-30","scope":"Azure networking overview; actual private connectivity also requires DNS and identity configuration."},{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."}],"stage":"intermediate","exercise":{"prompt":"Modify each forbidden property in a copy and run the negative tests. Identify an unmodeled risk, such as a broader inherited role assignment. Name the real control and observable denied test required to evaluate it.","checks":["Demonstrate each selected negative fixture case.","Name an unmodeled inherited-access risk and actual denied test."],"solution":"Changing public networking, omitting required tags or using Owner/wildcard roles must fail the selected local policy tests. An inherited Azure role or real network configuration remains outside this fixture model. Name actual provider-enforced controls and test allowed/denied behavior separately before claiming real enforcement.","solutionFormat":"prose"}},{"id":"secrets","title":"16. Secret lifecycle and workload identity","takeaway":"Reduce credential storage and test rotation and revocation.","sections":[{"title":"Understand the contract","paragraphs":["Prefer short-lived or federated identity where supported. Managed identity is for compatible Azure-hosted resources; local developer login and CI federation have different flows. Do not print credentials in CI logs or embed them in Terraform examples. Secret rotation should include consumers, overlapping validity where needed and proof that revoked credentials fail."]},{"title":"Work through the example","paragraphs":["A CI deployment exchanges a trusted workflow identity for a narrow Azure identity, while an application uses its own runtime identity. These identities must not be interchangeable. The optional template accepts no password or client secret and performs no real authentication in the offline lab."]}],"quiz":{"question":"Reduce credential storage and test rotation and revocation. Which decision follows?","options":["Use distinct short-lived deployment and runtime identities with revocation tests.","Reuse one long-lived secret across developers, CI and the application.","Revoke a secret in a worksheet and assume all existing sessions and cached tokens instantly stop working."],"correct":0,"explanation":"Separate identities improve attribution, expiry control and the scope of compromised access."},"references":[{"title":"Azure Terraform managed identity authentication","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/authenticate-to-azure-with-managed-identity-for-azure-services","section":"Configure and authenticate managed identity","reviewed":"2026-09-30","scope":"Azure-hosted identity workflow; a local workstation does not automatically receive managed identity."},{"title":"Azure role-based access control","url":"https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","section":"Principal; role definition; scope; additive assignments","reviewed":"2026-09-30","scope":"Azure management and supported data-plane authorization; notebook simulations do not authenticate to Azure."}],"stage":"intermediate","exercise":{"prompt":"Draw credential issuance, use, expiry and revocation. Define positive and denied tests. Label a localhost/mock token exercise as simulation rather than claiming that an identity provider was exercised.","checks":["Separate deployment and runtime credential flows.","Include expiry/revocation plus a negative test and its real execution boundary."],"solution":"Separate developer login, trusted CI federation and compatible hosted runtime identity. Document issuance, permitted use, expiry and revocation; test both positive access and denied revoked identity in the real environment. A localhost mock token does not exercise Azure identity enforcement, and no credential is supplied by this kit.","solutionFormat":"prose"}},{"id":"cost-control","title":"17. Cost estimation, budgets and cleanup","takeaway":"Budget alerts are not automatic spending caps.","sections":[{"title":"Understand the contract","paragraphs":["Include compute uptime, storage, transactions, egress, monitoring retention and idle resources in estimates. Provider prices vary by region and date, so use the current calculator when considering real spend. Azure budgets can notify and connect automation but do not by themselves stop charges. Set an owner, expiry and teardown verification."]},{"title":"Work through the example","paragraphs":["The offline model uses invented teaching rates: 2 units/hour times 10 hours plus 0.5 units/GB-month times 8 GB equals 24 units. These are not Azure prices. A private endpoint or monitoring workspace can add costs beyond storage, and deleting compute may leave disks or addresses.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"from infra_lab import estimate\n\nprint(estimate(2, 10, 0.5, 8))  # 24.0 fictional units\n# compute: 2 units/hour * 10 hours = 20\n# storage: 0.5 units/GB-month * 8 GB = 4\n# Not Azure pricing or a bill forecast."}],"quiz":{"question":"Budget alerts are not automatic spending caps. Which decision follows?","options":["Track all cost categories and verify resource removal instead of relying on alerts.","Assume an Azure budget automatically prevents overspending.","Set an expires tag and assume Azure automatically deletes the resources on that date."],"correct":0,"explanation":"A budget is a monitoring and notification mechanism unless separately integrated with controlled automation."},"references":[{"title":"Azure budgets","url":"https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets","section":"Create budgets; configure alerts","reviewed":"2026-09-30","scope":"Budgets notify and can integrate automation; a budget by itself does not cap or stop resource spending."},{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."}],"stage":"advanced","exercise":{"prompt":"Run the cost arithmetic test. Write a budget threshold plus an explicit response owner and cleanup inventory. For optional real work, confirm current regional prices and choose a tiny time-boxed isolated scope before provisioning anything.","checks":["Compute 24 fictional units without labeling them Azure prices.","Name cost categories, alert owner and observed cleanup checks."],"solution":"The invented teaching estimate is 20 compute units plus 4 storage units, total 24. Real review includes current regional compute, storage, transactions, egress, monitoring and idle costs. A budget needs an alert owner and response plan; it does not cap spending. Set expiry and verify teardown inventory instead of relying on tags alone.","solutionFormat":"prose"}},{"id":"deployment-pipeline","title":"18. CI planning and reviewed deployment","takeaway":"Separate untrusted validation from credentialed mutation.","sections":[{"title":"Understand the contract","paragraphs":["Run formatting, validation and policy checks before credentialed actions. Pull-request code may be untrusted and should not receive deployment secrets. Review plan artifacts, commit identity, environment and provider selection. Promotion should bind the reviewed code and configuration to the target environment and permit a deliberate rollback or recovery path."]},{"title":"Work through the example","paragraphs":["A pull request runs offline Python checks with no Azure identity. A trusted release job can obtain scoped identity and generate a target-specific plan, with protected review before deployment. The supplied kit has no CI cloud credentials or auto-apply pipeline."]}],"quiz":{"question":"Separate untrusted validation from credentialed mutation. Which decision follows?","options":["Keep untrusted checks unprivileged and bind deployment to a reviewed artifact.","Expose cloud credentials to every PR so plan checks are convenient.","Approve only the plan summary while letting an unreviewed release script choose the actual account and resources."],"correct":0,"explanation":"Untrusted executable code must not gain the privilege to mutate a real environment or exfiltrate its identity."},"references":[{"title":"Azure Terraform managed identity authentication","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/authenticate-to-azure-with-managed-identity-for-azure-services","section":"Configure and authenticate managed identity","reviewed":"2026-09-30","scope":"Azure-hosted identity workflow; a local workstation does not automatically receive managed identity."},{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."}],"stage":"advanced","exercise":{"prompt":"Create a pipeline sketch showing where secrets become available and what code can access them. Explain why reusing an unreviewed PR script in a privileged release step widens the trust boundary.","checks":["Mark exactly where cloud identity becomes available.","Explain how unreviewed executable code is kept out of privileged release steps."],"solution":"Untrusted PR code runs offline checks without cloud identity. A trusted release uses reviewed artifacts and a deliberately scoped short-lived identity under protected environment rules. Review where executable code can access that identity; invoking an unreviewed PR script inside a privileged job crosses the trust boundary.","solutionFormat":"prose"},"diagram":{"title":"Untrusted checks and privileged release","summary":"Identity becomes available only inside the reviewed release boundary.","nodes":[{"id":"0","label":"Pull request","description":"Potentially untrusted source."},{"id":"1","label":"Offline checks","description":"No Azure credentials."},{"id":"2","label":"Reviewed release artifact","description":"Bind reviewed commit and environment."},{"id":"3","label":"Scoped deployment identity","description":"Short-lived authorized release access."},{"id":"4","label":"Target scope","description":"Only the chosen environment."}],"edges":[{"from":"0","to":"1","label":"validate unprivileged"},{"from":"1","to":"2","label":"review and promote"},{"from":"2","to":"3","label":"trusted release boundary"},{"from":"3","to":"4","label":"scoped operation"}],"steps":[{"title":"1. validate unprivileged","activeNodes":["0","1"],"activeEdges":[0],"explanation":"No Azure credentials."},{"title":"2. review and promote","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Bind reviewed commit and environment."},{"title":"3. trusted release boundary","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Short-lived authorized release access."},{"title":"4. scoped operation","activeNodes":["3","4"],"activeEdges":[3],"explanation":"Only the chosen environment."}],"direction":"LR"}},{"id":"infra-tests","title":"19. Infrastructure tests and mock boundaries","takeaway":"Distinguish syntax, model, provider and deployed-service tests.","sections":[{"title":"Understand the contract","paragraphs":["JSON parsing checks syntax. Offline model tests check selected arithmetic and policy invariants. terraform validate checks language and provider schema after initialization. A plan can consult cloud APIs. Terraform test may create real resources unless runs are explicitly planned or providers mocked with compatible versions. Deployed smoke tests examine actual endpoints and identities."]},{"title":"Work through the example","paragraphs":["The supplied suite executes only local Python/SQLite-free inventory modeling, while optional init/validate checks the AzureRM schema without apply. Mock Terraform tests are discussed as an extension requiring Terraform 1.7+; they do not establish real service reachability.","Run Python snippets from the extracted practice folder with the supplied reference files. JSON fragments show the stated contract; they are not a complete deployment configuration."],"example":"python infra_lab.py\npython -m unittest -v test_infra_lab.py"}],"quiz":{"question":"Distinguish syntax, model, provider and deployed-service tests. Which decision follows?","options":["Name the exact execution boundary for each passing check.","Assume terraform test is always safe and offline by default.","Treat Terraform validate as a test of current subscription permissions and resource name availability."],"correct":0,"explanation":"Terraform test can provision resources; explicit run and provider choices determine behavior and potential cost."},"references":[{"title":"Terraform tests","url":"https://developer.hashicorp.com/terraform/language/tests","section":"Tests; run blocks; mocked providers","reviewed":"2026-09-30","scope":"Terraform testing can use real resources by default; mock provider support requires compatible Terraform, introduced in 1.7."},{"title":"Terraform on Azure overview","url":"https://learn.microsoft.com/en-us/azure/developer/terraform/overview","section":"Terraform on Azure","reviewed":"2026-09-30","scope":"Azure Terraform introduction; provider releases and resource availability remain changeable."}],"stage":"advanced","exercise":{"prompt":"Build an evidence table with syntax, static policy, provider validation and deployed positive/negative tests. Mark the latter as not executed. Do not equate a mocked provider result with a successful live deployment.","checks":["Create distinct syntax, model, provider and deployed-service evidence rows.","Mark unexecuted live tests honestly and explain Terraform-test cost behavior."],"solution":"JSON parsing establishes syntax; local Python tests establish this inventory model's rules; initialized Terraform validate checks language/provider schema. A real plan/deployment and allowed/denied endpoint tests require a chosen environment. Terraform test can provision by default unless explicitly configured for planned/mocked behavior with compatible versions.","solutionFormat":"prose"}},{"id":"resilience","title":"20. Recovery, backups and failure domains","takeaway":"Infrastructure reconstruction and data restoration are separate plans.","sections":[{"title":"Understand the contract","paragraphs":["A region, zone, account or identity failure can affect different parts of a workload. Rebuilding infrastructure from code does not restore database rows or blob contents. Define recovery point and time objectives, protect backups separately, and rehearse isolated restoration with real synthetic verification when choosing a live environment."]},{"title":"Work through the example","paragraphs":["If an export file store is lost, Terraform can create another account but cannot invent its missing files. If state is lost while the cloud survives, preserve resource identity and adopt carefully rather than creating duplicates. A rollback can also fail if data migrations are incompatible."]}],"quiz":{"question":"Infrastructure reconstruction and data restoration are separate plans. Which decision follows?","options":["Restore infrastructure identity and application data through separate verified steps.","Claim RPO is zero because configuration is committed to Git.","Reapply the same configuration after data deletion and assume the recreated account contains its previous blobs."],"correct":0,"explanation":"Git configuration preserves intended topology, not necessarily application state or completed writes."},"references":[{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."},{"title":"Terraform state","url":"https://developer.hashicorp.com/terraform/language/state","section":"Purpose of Terraform state","reviewed":"2026-09-30","scope":"Terraform 1.x language guidance; the offline inventory is a teaching model, not a Terraform state implementation."}],"stage":"advanced","exercise":{"prompt":"Write separate runbooks for lost state, deleted storage and compromised identity. For each, name the evidence required before resuming user traffic. Offline plan tests do not measure real RTO or backup integrity.","checks":["Separate state loss, data loss and identity compromise recovery.","Name evidence before resuming traffic and avoid invented RPO/RTO."],"solution":"Lost state with surviving resources needs protected state recovery or careful adoption of their identities. Deleted storage needs application-data backups and verified restore, not just new resource definitions. Compromised identity needs revocation, rotated access and investigation before traffic resumes. Each runbook names owners and observed validation.","solutionFormat":"prose"}},{"id":"cleanup","title":"21. Teardown and leftover resources","takeaway":"Deletion needs scope checks and post-deletion verification.","sections":[{"title":"Understand the contract","paragraphs":["Review destroy plans as carefully as creates. Confirm subscription and resource identity, preserve needed data, and inspect provider-dependent order and deletion protections. Destroy may fail partway, leave soft-deleted objects or retain resources outside the managed state. Cost and data-retention cleanup need observed verification, not merely a command exit."]},{"title":"Work through the example","paragraphs":["The offline planner refuses destroy actions without an explicit opt-in; it never calls Azure. For an independently chosen isolated real lab, review terraform plan -destroy before any terraform destroy, then check the portal and remaining state. A resource group must contain only your disposable learning resources."]}],"quiz":{"question":"Deletion needs scope checks and post-deletion verification. Which decision follows?","options":["Confirm disposable ownership, review destruction and check leftovers afterward.","Assume a successful destroy means every related charge and copy of data is gone.","Delete the resource group as a shortcut even when it contains unrelated resources absent from Terraform state."],"correct":0,"explanation":"State ownership, soft deletion and external resources can leave costs or retained data beyond the managed deletion."},"references":[{"title":"Terraform lifecycle","url":"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle","section":"create_before_destroy; prevent_destroy; ignore_changes","reviewed":"2026-09-30","scope":"Terraform lifecycle behavior, including limitations; no resource lifecycle operation is executed here."},{"title":"Azure budgets","url":"https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets","section":"Create budgets; configure alerts","reviewed":"2026-09-30","scope":"Budgets notify and can integrate automation; a budget by itself does not cap or stop resource spending."}],"stage":"advanced","exercise":{"prompt":"Complete the teardown checklist in workbook.md. List resources excluded from Terraform ownership, monitoring exports and backups. Never run a resource-group deletion against a computed or unverified shared scope.","checks":["Verify ownership/scope before destructive work.","List external/retained objects and observable post-deletion checks."],"solution":"Check exact subscription and disposable resource ownership, preserve required synthetic evidence/data, review the destroy plan and deliberately delete only owned learning resources. Verify state, portal inventory, retained/soft-deleted objects and external monitoring/backups afterward. An operation exit cannot establish that every cost source or retained copy disappeared.","solutionFormat":"prose"}},{"id":"launch-review","title":"22. Infrastructure launch decision","takeaway":"Use an evidence portfolio to separate design confidence from production readiness.","sections":[{"title":"Understand the contract","paragraphs":["A reviewable portfolio has an ADR, scope and identity map, resource graph, plan classification, data restore plan, cost categories, cleanup procedure and evidence ledger. Record which local tests passed, which provider checks ran and which real deployment questions remain. A complete course is bounded learning rather than a certification of an operated cloud system."]},{"title":"Work through the example","paragraphs":["The advanced project designs a private full-stack notebook and reviews public networking, state exposure, replacement and credentialed CI risks. It keeps the static notebook unchanged and does not provision cloud resources. Optional live work needs an explicit chosen account, cost limit, ownership and teardown."]}],"quiz":{"question":"Use an evidence portfolio to separate design confidence from production readiness. Which decision follows?","options":["Tie readiness claims to actual evidence and name remaining live experiments.","Declare production-ready after finishing all reading and quizzes.","Interpret provider-schema validation as proof that the complete full-stack application is production-ready."],"correct":0,"explanation":"Reading and local tests build a foundation, while operated systems need evidence at their real service boundaries."},"references":[{"title":"Azure Well-Architected Framework","url":"https://learn.microsoft.com/en-us/azure/well-architected/","section":"Reliability; security; cost; operations; performance pillars","reviewed":"2026-09-30","scope":"Azure architecture guidance; mock checks do not establish production readiness."},{"title":"Terraform tests","url":"https://developer.hashicorp.com/terraform/language/tests","section":"Tests; run blocks; mocked providers","reviewed":"2026-09-30","scope":"Terraform testing can use real resources by default; mock provider support requires compatible Terraform, introduced in 1.7."},{"title":"Azure budgets","url":"https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets","section":"Create budgets; configure alerts","reviewed":"2026-09-30","scope":"Budgets notify and can integrate automation; a budget by itself does not cap or stop resource spending."}],"stage":"advanced","exercise":{"prompt":"Present a go/no-go decision with three unresolved risks and a concrete next experiment for each. Reject any claim based solely on a mock test when it requires actual network, identity, data or cost evidence.","checks":["Bind each readiness claim to actual observed or explicitly missing evidence.","Provide three unresolved risks with a next experiment and decision trigger."],"solution":"Present an ADR and identity/network graph, protected state design, plan classification, data recovery, cost categories and verified-cleanup proposal. Record local executed tests, optional provider validation and unexecuted live claims separately. Three go/no-go risks can be denied-access evidence, restore integrity and private-connectivity checks, each with a concrete next experiment.","solutionFormat":"prose"}}],"stages":[{"id":"foundation","title":"Cloud responsibility and scope map","description":"Design a small hypothetical private notebook without creating resources.","exitCriteria":["Every operational responsibility has an owner.","Network reachability and permission are distinct.","Current cloud prices are not invented."],"project":{"title":"Cloud responsibility and scope map","brief":"Design a small hypothetical private notebook without creating resources.","requirements":["Compare static and managed app responsibilities.","Name tenant, subscription, region and disposable scope.","Draw network and identity gates.","List cost categories and data owners."],"rubric":["Every operational responsibility has an owner.","Network reachability and permission are distinct.","Current cloud prices are not invented."],"solution":"Retain static hosting until authenticated writes are needed. Map client/API/storage identities and routes, and choose an isolated learning scope with owner and expiry. Estimate categories, then consult current regional pricing before real spend.","solutionFormat":"prose"}},{"id":"intermediate","title":"Reviewed infrastructure plan","description":"Run the offline planner and inspect the optional Azure Terraform JSON.","exitCriteria":["Model output is not presented as Terraform output.","Destruction and replacement include data consequences.","Provider validation is distinct from deployment."],"project":{"title":"Reviewed infrastructure plan","brief":"Run the offline planner and inspect the optional Azure Terraform JSON.","requirements":["Run positive and negative tests.","Classify create/update/replace/destroy.","Review typed inputs, state handling and dependencies.","Optionally init/validate in a separate empty folder; record results."],"rubric":["Model output is not presented as Terraform output.","Destruction and replacement include data consequences.","Provider validation is distinct from deployment."],"solution":"Use the teaching planner to prove its explicit policy and operation contract. The optional provider-backed template needs Terraform initialization, an actual locked AzureRM selection and validate; it does not provide private application connectivity or perform a deployment.","solutionFormat":"prose"}},{"id":"advanced","title":"Cloud launch and teardown review","description":"Prepare an evidence portfolio for a future full-stack deployment.","exitCriteria":["No mock result becomes a real cloud claim.","State and application data recovery are separate.","Cleanup checks ownership and leftovers."],"project":{"title":"Cloud launch and teardown review","brief":"Prepare an evidence portfolio for a future full-stack deployment.","requirements":["Separate PR checks from privileged release steps.","Design state, identity and data recovery.","Create cost, expiry and cleanup checklists.","Specify real denied-access, restore and smoke tests still needed."],"rubric":["No mock result becomes a real cloud claim.","State and application data recovery are separate.","Cleanup checks ownership and leftovers."],"solution":"Review the exact resource graph and identity scopes, protected state and credential boundaries; rehearse data recovery in an independently chosen environment. Confirm budget alerts are not a cap. Scope-check and review every deletion, then verify retained objects and cost sources.","solutionFormat":"prose"}}],"downloads":[{"title":"Complete runnable practice kit","href":"paths/cloud-infrastructure/practice-bundle.zip"}],"resources":{"folder":"cloud-infrastructure-practice","files":[{"id":"infra_lab-py","href":"paths/cloud-infrastructure/practice/infra_lab.py","role":"reference","description":"Reference implementation or clearly labeled training configuration."},{"id":"test_infra_lab-py","href":"paths/cloud-infrastructure/practice/test_infra_lab.py","role":"test","description":"Locally runnable regression tests."},{"id":"topology-json","href":"paths/cloud-infrastructure/practice/topology.json","role":"reference","description":"Reference implementation or clearly labeled training configuration."},{"id":"main-tf-json","href":"paths/cloud-infrastructure/practice/main.tf.json","role":"reference","description":"Reference implementation or clearly labeled training configuration."},{"id":"README-md","href":"paths/cloud-infrastructure/practice/README.md","role":"guide","description":"Runtime, exact commands, expected results, cleanup and execution boundaries."},{"id":"workbook-md","href":"paths/cloud-infrastructure/practice/workbook.md","role":"guide","description":"Three projects, exercises, evidence ledger and reference reasoning."}],"tasks":[{"id":"foundation","title":"Cloud responsibility and scope map","goal":"Design a small hypothetical private notebook without creating resources.","fileIds":["infra_lab-py","test_infra_lab-py","topology-json","main-tf-json","README-md","workbook-md"],"steps":["Extract the flat files and read README.md.","Compare static and managed app responsibilities.","Name tenant, subscription, region and disposable scope.","Draw network and identity gates.","List cost categories and data owners.","Compare your findings with workbook.md and the stage rubric."],"commands":[{"label":"Run local demonstration","command":"python infra_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_infra_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim."]},{"id":"intermediate","title":"Reviewed infrastructure plan","goal":"Run the offline planner and inspect the optional Azure Terraform JSON.","fileIds":["infra_lab-py","test_infra_lab-py","topology-json","main-tf-json","README-md","workbook-md"],"steps":["Extract the flat files and read README.md.","Run positive and negative tests.","Classify create/update/replace/destroy.","Review typed inputs, state handling and dependencies.","Optionally init/validate in a separate empty folder; record results.","Compare your findings with workbook.md and the stage rubric."],"commands":[{"label":"Run local demonstration","command":"python infra_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_infra_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim."]},{"id":"advanced","title":"Cloud launch and teardown review","goal":"Prepare an evidence portfolio for a future full-stack deployment.","fileIds":["infra_lab-py","test_infra_lab-py","topology-json","main-tf-json","README-md","workbook-md"],"steps":["Extract the flat files and read README.md.","Separate PR checks from privileged release steps.","Design state, identity and data recovery.","Create cost, expiry and cleanup checklists.","Specify real denied-access, restore and smoke tests still needed.","Compare your findings with workbook.md and the stage rubric."],"commands":[{"label":"Run local demonstration","command":"python infra_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_infra_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim."]}],"lessonTasks":{"cloud-contract":"foundation","azure-scope":"foundation","requirements":"foundation","networking":"foundation","identity":"foundation","iac-model":"foundation","provider-init":"foundation","variables":"foundation","dependencies":"intermediate","state":"intermediate","plan-review":"intermediate","lifecycle":"intermediate","modules":"intermediate","drift-import":"intermediate","policy":"intermediate","secrets":"intermediate","cost-control":"advanced","deployment-pipeline":"advanced","infra-tests":"advanced","resilience":"advanced","cleanup":"advanced","launch-review":"advanced"},"bundle":{"href":"paths/cloud-infrastructure/practice-bundle.zip"}}});
